        for (i = 0; i < MESSAGE_FD_MAX; i++)
                if (asyncns->fds[i] >= 0)
                        close(asyncns->fds[i]);

        for (p = 0; p < MAX_QUERIES; p++)
                if (asyncns->queries[p])
                        asyncns_cancel(asyncns, asyncns->queries[p]);

        free(asyncns);

        errno = saved_errno;
}

